create or replace function gov_repo.compute_dora_reporting_deadlines() returns trigger language plpgsql as $$ begin if new.is_major_incident=true and (old.is_major_incident is distinct from true) then new.initial_notification_deadline:=now()+interval '4 hours';new.intermediate_report_deadline:=now()+interval '72 hours';new.final_report_deadline:=now()+interval '1 month';new.reporting_phase:='initial_notification';end if;if new.initial_notification_sent_at is not null and old.initial_notification_sent_at is null then new.intermediate_report_deadline:=new.initial_notification_sent_at+interval '72 hours';new.final_report_deadline:=new.initial_notification_sent_at+interval '1 month';new.reporting_phase:='intermediate_report';end if;if new.intermediate_report_sent_at is not null and old.intermediate_report_sent_at is null then new.reporting_phase:='final_report';end if;if new.final_report_sent_at is not null and old.final_report_sent_at is null then new.reporting_phase:='all_complete';end if;if new.pii_data_exposed=true and old.pii_data_exposed is distinct from true and new.dpa_notification_deadline is null then new.dpa_notification_deadline:=coalesce(new.detected_at,now())+interval '72 hours';end if;if new.primary_ai_system_id is not null then new.involves_ai_system:=true;end if;if new.primary_provider_id is not null then new.involves_third_party:=true;end if;return new;end;$$;
create trigger trg_ict_inc_dora_deadlines before insert or update on gov_repo.ict_incidents for each row execute function gov_repo.compute_dora_reporting_deadlines();
create or replace function gov_repo.sync_ai_system_incident_count() returns trigger language plpgsql as $$ begin if new.primary_ai_system_id is not null and new.status='closed' and (old.status is null or old.status!='closed') then update gov_repo.ai_systems set serious_incidents_reported=serious_incidents_reported+1,last_serious_incident_at=now() where system_id=new.primary_ai_system_id;end if;return new;end;$$;
create trigger trg_ict_inc_ai_system_sync after insert or update of status,primary_ai_system_id on gov_repo.ict_incidents for each row execute function gov_repo.sync_ai_system_incident_count();
drop policy if exists "Org-scoped ict_incidents" on gov_repo.ict_incidents;
create policy "Authenticated read ict_incidents" on gov_repo.ict_incidents for select to authenticated using(organisation_id=(select organisation_id from gov_repo.governance_users where email=auth.email() limit 1));
create policy "Incident reporters can insert" on gov_repo.ict_incidents for insert to authenticated with check(organisation_id=(select organisation_id from gov_repo.governance_users where email=auth.email() limit 1) and reported_by=(select user_id from gov_repo.governance_users where email=auth.email() limit 1));
create or replace view gov_repo.v_ict_major_incident_dashboard as select i.organisation_id,i.incident_id,i.incident_code,i.title,i.severity,i.incident_category,i.status,i.recovery_status,i.reporting_phase,i.occurred_at,i.detected_at,i.reported_at,i.contained_at,i.recovery_completed_at,i.closed_at,round(extract(epoch from(i.detected_at-i.occurred_at))/3600.0,1) as detection_lag_hours,i.is_major_incident,i.competent_authority,i.nca_case_ref,i.initial_notification_deadline,i.initial_notification_sent_at,(i.initial_notification_sent_at is null and i.initial_notification_deadline<now()) as initial_notif_breached,round(extract(epoch from(i.initial_notification_deadline-now()))/3600.0,1) as initial_notif_hours_remaining,i.intermediate_report_deadline,i.intermediate_report_sent_at,(i.intermediate_report_sent_at is null and i.intermediate_report_deadline<now()) as intermediate_report_breached,i.final_report_deadline,i.final_report_sent_at,(i.final_report_sent_at is null and i.final_report_deadline<now()) as final_report_breached,i.rto_target_minutes,i.rto_actual_minutes,i.rto_breach,i.involves_ai_system,s.name as primary_ai_system_name,s.risk_class as ai_system_risk_class,i.ai_act_reporting_required,i.involves_third_party,p.name as primary_provider_name,p.dora_criticality as provider_dora_criticality,i.concentration_risk_flag,i.pii_data_exposed,i.gdpr_breach_notified,i.dpa_notification_deadline,(i.pii_data_exposed=true and i.gdpr_breach_notified=false and i.dpa_notification_deadline<now()) as gdpr_deadline_breached,i.financial_impact_eur,i.direct_financial_loss_eur,u_cmd.full_name as incident_commander,u_rep.full_name as reporting_owner,u_rpt.full_name as reported_by_name,(select count(*) from gov_repo.ict_incident_affected_services svc where svc.incident_id=i.incident_id) as affected_services_count,(select count(*) from gov_repo.ict_incident_affected_services svc where svc.incident_id=i.incident_id and svc.rto_breach=true) as services_with_rto_breach,(select count(*) from gov_repo.ict_incident_notifications n where n.incident_id=i.incident_id) as notifications_submitted,(select count(*) from gov_repo.ict_incident_notifications n where n.incident_id=i.incident_id and n.is_breached=true) as notifications_breached from gov_repo.ict_incidents i left join gov_repo.ai_systems s on s.system_id=i.primary_ai_system_id left join gov_repo.third_party_providers p on p.provider_id=i.primary_provider_id left join gov_repo.governance_users u_cmd on u_cmd.user_id=i.incident_commander_id left join gov_repo.governance_users u_rep on u_rep.user_id=i.reporting_owner_id left join gov_repo.governance_users u_rpt on u_rpt.user_id=i.reported_by where i.is_major_incident=true and i.status not in ('closed') order by case i.severity when 'critical' then 1 when 'high' then 2 when 'medium' then 3 else 4 end,i.occurred_at desc nulls last;;
